-- Read-only coverage input for the offline planner.
SELECT t."Code" AS track,t."StageId" AS stage,c."Id" AS "categoryId",c."NameAr" AS "categoryAr",c."NameEn" AS "categoryEn",count(DISTINCT p."Id") AS questions FROM "LearningTracks" t LEFT JOIN "LearningTrackCategories" tc ON tc."TrackId"=t."Id" LEFT JOIN "Categories" c ON c."Id"=tc."CategoryId" LEFT JOIN "LearningTrackProblems" tp ON tp."TrackId"=t."Id" LEFT JOIN "Problems" p ON p."Id"=tp."ProblemId" AND p."CategoryId"=c."Id" WHERE t."IsPublished" GROUP BY t."Code",t."StageId",c."Id",c."NameAr",c."NameEn" ORDER BY t."StageId",t."Code",c."Id";
